using UnityEngine;
using UnityEngine.InputSystem;
using TMPro;
using DG.Tweening;
using LWS.TruckSports;
namespace LWS.TruckHockey {
public enum HockeyScreen {Setup,Join,Match,Pause,Help,Settings,Confirm,Disconnect,Result}
public sealed class HockeyMenus:SportsMenuView {
 public HockeyMatch match;public HockeyScreen Screen=HockeyScreen.Setup;public TMP_InputField name1,name2;
 public TMP_Text modeText,soloText,color1Text,color2Text,difficultyText,durationText,setupInfo,joinInfo,disconnectInfo,scoreText,clockText,teamText,messageText,controlsText,resultText,helpText,confirmText;
 public GameObject hud;public RectTransform resultTitle;public RectTransform[] confetti;public Color[] palette={new Color(.15f,.8f,1),new Color(1,.55f,.13f),new Color(.85f,.25f,.7f),new Color(.6f,1,.3f),new Color(.9f,.85f,.25f)};
 int color1,color2=1;HockeyScreen returnScreen;string confirmation;float nextHud;bool joinNavigationReady;readonly System.Collections.Generic.List<Tween> tweens=new System.Collections.Generic.List<Tween>();
 const string Controls="Both trucks can hit the puck at any time. Drive into it; no shooting button.\n\nP1 keyboard: WASD • Space brake • R recover • Esc pause\nP2 shared keyboard: arrows • Right Shift brake • Enter recover\nAssigned controller: left stick steer • RT accelerate • LT reverse\nSouth / A / Cross brake • North / Y / Triangle recover • Start / Menu pause\n\nRecover: only your truck, safe own-half position, 2-second cooldown.\nA fully crossed goal line through the mouth scores for the attacker, including own goals.\nRegulation runs only during live play. A tie starts sudden-death overtime.\nRematch preserves setup and swaps rink ends. No offsides, icing or penalties.";
 protected override void Start(){base.Start();name1.onEndEdit.AddListener(v=>{match.players[0].name=string.IsNullOrWhiteSpace(v)?"Player 1":v;RefreshSetup();});name2.onEndEdit.AddListener(v=>{match.players[1].name=string.IsNullOrWhiteSpace(v)?"Player 2":v;RefreshSetup();});Show(Screen);}
 public void Show(HockeyScreen screen){Screen=screen;feedback.StopMotors();if(screen!=HockeyScreen.Result)ClearCelebration();hud.SetActive(screen==HockeyScreen.Match);base.Show((int)screen);if(screen==HockeyScreen.Setup)RefreshSetup();if(screen==HockeyScreen.Join||screen==HockeyScreen.Disconnect)RefreshJoin();if(screen==HockeyScreen.Help)helpText.text=Controls;if(screen==HockeyScreen.Settings)SettingsText();if(screen==HockeyScreen.Result){resultText.text=match.PlayerName(match.rules.Winner).ToUpper()+" WINS\n"+match.PlayerName(0)+"  "+match.rules.Score[0]+" : "+match.rules.Score[1]+"  "+match.PlayerName(1)+(match.rules.Overtime?"\nSUDDEN-DEATH VICTORY":"\nREGULATION COMPLETE");resultText.color=match.players[match.rules.Winner].color;}Focus();RefreshHUD();if(screen==HockeyScreen.Match){scoreText.ForceMeshUpdate();clockText.ForceMeshUpdate();teamText.ForceMeshUpdate();messageText.ForceMeshUpdate();controlsText.ForceMeshUpdate();}}
 public override void Action(string key){base.Action(key);switch(key){case "mode":match.mode=(HockeyMode)(((int)match.mode+1)%4);match.Configure();RefreshSetup();break;case "solo":match.soloController=!match.soloController;match.Configure();RefreshSetup();break;case "color1":color1=(color1+1)%palette.Length;if(color1==color2)color1=(color1+1)%palette.Length;match.players[0].color=palette[color1];RefreshSetup();break;case "color2":color2=(color2+1)%palette.Length;if(color1==color2)color2=(color2+1)%palette.Length;match.players[1].color=palette[color2];RefreshSetup();break;case "difficulty":match.difficulty=(HockeyDifficulty)(((int)match.difficulty+1)%3);PlayerPrefs.SetInt("TruckHockey.Difficulty",(int)match.difficulty);PlayerPrefs.Save();RefreshSetup();break;case "duration":match.durationMinutes=match.durationMinutes==2?3:match.durationMinutes==3?5:2;RefreshSetup();break;case "start":match.Configure();if(!match.DevicesReady)Show(HockeyScreen.Join);else match.StartMatch();break;case "resume":match.Resume();break;case "reassign0":match.Unassign(0);RefreshJoin();break;case "reassign1":match.Unassign(1);RefreshJoin();break;case "controls":returnScreen=Screen;Show(HockeyScreen.Help);break;case "settings":returnScreen=Screen;Show(HockeyScreen.Settings);break;case "back":Back();break;case "restart":confirmation="restart";confirmText.text="RESTART MATCH?\nScores and clock will reset. Your current rink ends and setup are retained.";Show(HockeyScreen.Confirm);break;case "front":if(match.InMatch&&match.rules.Phase!=HockeyPhase.Finished){confirmation="front";confirmText.text="RETURN TO SPORT SELECTION?\nThe current hockey match will be abandoned.";Show(HockeyScreen.Confirm);}else SportsNavigation.FrontEnd();break;case "yes":if(confirmation=="restart")match.Restart();else SportsNavigation.FrontEnd();break;case "no":Show(HockeyScreen.Pause);break;case "rematch":match.StartMatch(true);break;case "setup":match.ChangeSetup();break;}}
 public void Back(){if(Screen==HockeyScreen.Setup)SportsNavigation.FrontEnd();else if(Screen==HockeyScreen.Join)match.ChangeSetup();else if(Screen==HockeyScreen.Help||Screen==HockeyScreen.Settings)Show(returnScreen);else if(Screen==HockeyScreen.Confirm)Show(HockeyScreen.Pause);else if(Screen==HockeyScreen.Pause||Screen==HockeyScreen.Disconnect)match.Resume();}
 public void RefreshSetup(){modeText.text=new[]{"PLAYER vs AI","TWO PLAYERS • SHARED KEYBOARD","TWO PLAYERS • SEPARATE CONTROLLERS","KEYBOARD vs CONTROLLER"}[(int)match.mode];soloText.transform.parent.gameObject.SetActive(match.AIEnabled);soloText.text="Player device: "+(match.soloController?"ONE ASSIGNED CONTROLLER":"KEYBOARD");difficultyText.transform.parent.gameObject.SetActive(match.AIEnabled);difficultyText.text="AI: "+match.difficulty.ToString().ToUpper();durationText.text="Duration: "+match.durationMinutes+" MINUTES";name1.SetTextWithoutNotify(match.players[0].name);name2.SetTextWithoutNotify(match.PlayerName(1));name2.interactable=!match.AIEnabled;color1Text.text="Team color: "+new[]{"BLUE","ORANGE","MAGENTA","LIME","GOLD"}[color1];color2Text.text="Team color: "+new[]{"BLUE","ORANGE","MAGENTA","LIME","GOLD"}[color2];color1Text.color=match.players[0].color;color2Text.color=match.players[1].color;setupInfo.text="Required: "+(match.mode==HockeyMode.SeparateControllers?"TWO distinct controllers":match.mode==HockeyMode.KeyboardController?"ONE keyboard + ONE assigned controller":match.soloController&&match.AIEnabled?"ONE assigned controller":"ONE keyboard")+"\nNorth / Y / Triangle joins a controller on the next screen. Default names are ready to play.\nSimultaneous hockey • no hot seat • recover only your own truck";Focus();}
 public void RefreshJoin(){bool ready=match.DevicesReady;string info="Press NORTH / Y / TRIANGLE to join the first empty assigned slot.\n\n";for(int i=0;i<2;i++)info+=match.PlayerName(i)+": "+(i==1&&match.AIEnabled?"AI":!match.players[i].controller?"Keyboard":match.Ready(i)?match.players[i].pad.displayName+" • ID "+match.players[i].pad.deviceId:"CONTROLLER MISSING / DISCONNECTED")+"\n";info+="\nReconnect the same controller, or Reassign the missing slot and join a replacement.\nOne controller cannot control both trucks. Resume requires fresh controls.";joinInfo.text=disconnectInfo.text=info;foreach(var screen in new[]{HockeyScreen.Join,HockeyScreen.Disconnect})foreach(var action in pages[(int)screen].GetComponentsInChildren<SportsMenuAction>(true)){if(action.action=="reassign0")action.gameObject.SetActive(match.players[0].controller);if(action.action=="reassign1")action.gameObject.SetActive(match.players[1].controller);if(action.action=="start"||action.action=="resume"){action.button.isInteractable=ready;action.GetComponent<UnityEngine.UI.Button>().interactable=ready;}}if(ready!=joinNavigationReady){joinNavigationReady=ready;Focus();}}
 public void RefreshHUD(){if(!match.InMatch)return;scoreText.text="<color=#"+ColorUtility.ToHtmlStringRGB(match.players[0].color)+">"+match.PlayerName(0)+"  "+match.rules.Score[0]+"</color>   :   <color=#"+ColorUtility.ToHtmlStringRGB(match.players[1].color)+">"+match.rules.Score[1]+"  "+match.PlayerName(1)+"</color>";clockText.text=match.rules.Overtime?"OVERTIME • SUDDEN DEATH":(Mathf.CeilToInt(match.rules.Remaining)/60).ToString("00")+":"+(Mathf.CeilToInt(match.rules.Remaining)%60).ToString("00");teamText.text=match.PlayerName(0)+" defends "+(match.rules.DefendingSign(0)<0?"LEFT":"RIGHT")+"    •    "+match.PlayerName(1)+" defends "+(match.rules.DefendingSign(1)<0?"LEFT":"RIGHT")+(match.AIEnabled?"    •    AI "+match.difficulty.ToString().ToUpper():"");var phase=match.rules.Phase;messageText.text=phase==HockeyPhase.Pregame||phase==HockeyPhase.Faceoff?((phase==HockeyPhase.Faceoff&&match.Notice.StartsWith("PUCK RECOVERY"))?"PUCK RECOVERY • FAIR FACEOFF  ":"FACEOFF  ")+Mathf.Max(1,Mathf.CeilToInt(match.rules.PhaseTimer)):phase==HockeyPhase.Goal?"GOAL!  "+match.PlayerName(match.rules.LastScorer):match.Notice;controlsText.text="WASD / arrows or assigned pad: drive  •  Brake: Space / Right Shift / South\nRecover: R / Enter / North  •  Pause: Esc / Start  •  No shooting button";}
 public void Celebrate(Color color,bool winner){ClearCelebration();int count=winner?confetti.Length:confetti.Length/2;for(int i=0;i<count;i++){var r=confetti[i];r.gameObject.SetActive(true);r.GetComponent<UnityEngine.UI.Image>().color=i%3==0?Color.white:color;Vector2 from=new Vector2((i%2==0?-1:1)*(330+i%8*18),150);r.anchoredPosition=from;var to=from+new Vector2((i%2==0?-1:1)*35,-190-i%4*20);tweens.Add(DOTween.To(()=>r.anchoredPosition,v=>r.anchoredPosition=v,to,winner?1.5f:1).SetEase(Ease.OutQuad).SetUpdate(true).OnComplete(()=>r.gameObject.SetActive(false)));}if(winner)tweens.Add(resultTitle.DOScale(1.06f,.18f).SetLoops(2,LoopType.Yoyo).SetUpdate(true));}
 public void ClearCelebration(){foreach(var t in tweens)if(t!=null&&t.IsActive())t.Kill();tweens.Clear();if(confetti!=null)foreach(var c in confetti)if(c!=null)c.gameObject.SetActive(false);if(resultTitle!=null)resultTitle.localScale=Vector3.one;}
 protected override void Update(){base.Update();if(Screen==HockeyScreen.Join||Screen==HockeyScreen.Disconnect)RefreshJoin();foreach(var p in Gamepad.all)if(menuInput.Down(p,8)&&Screen!=HockeyScreen.Match){Back();break;}if(Time.unscaledTime>=nextHud){nextHud=Time.unscaledTime+.1f;RefreshHUD();}}
 void OnDisable(){ClearCelebration();}
}
}



